    'online.countOne': ['You are the only one online right now – the moment someone opens the game, you are matched.', 'Tani je vetëm ti online – sapo dikush të hapë lojën, ju bashkojmë.', 'Du bist gerade allein online – sobald jemand das Spiel öffnet, werdet ihr verbunden.', 'Trenutno si jedini online – čim neko otvori igru, spajamo vas.'],
    'online.reconnect': ['The connection dropped – connecting again…', 'Lidhja u ndërpre – po lidhemi përsëri…', 'Verbindung unterbrochen – neuer Versuch…', 'Veza je prekinuta – povezujemo se ponovo…'],
    'online.langAsk': ['{name} plays in {lang}. This game would be in {lang} – questions and answers too. Play anyway?', '{name} luan në {lang}. Kjo lojë do të jetë në {lang} – edhe pyetjet e përgjigjet. Të luash gjithsesi?', '{name} spielt auf {lang}. Dieses Spiel wäre auf {lang} – auch Fragen und Antworten. Trotzdem spielen?', '{name} igra na jeziku {lang}. Ova igra bi bila na jeziku {lang} – i pitanja i odgovori. Ipak igrati?'],
    'online.langTheirs': ['{name} usually plays in {theirs}; this game will be in {lang}, your language.', '{name} zakonisht luan në {theirs}; kjo lojë do të jetë në {lang}, gjuhën tënde.', '{name} spielt sonst auf {theirs}; dieses Spiel ist auf {lang}, deiner Sprache.', '{name} obično igra na jeziku {theirs}; ova igra će biti na jeziku {lang}, tvom jeziku.'],
