    // 1.1.7 - ending a match by agreement
    'agree.ask': ['Ask {name} to end the match – nothing counts', 'Kërkoji {name} ta mbyllni ndeshjen – asgjë nuk llogaritet', '{name} bitten, die Partie zu beenden – nichts zählt', 'Zamoli {name} da završite partiju – ništa se ne računa'],
    'agree.askHint': ['If {name} agrees, the match ends for both of you: no winner, no points lost, no rating change.', 'Nëse {name} pranon, ndeshja mbyllet për të dy: pa fitues, pa pikë të humbura, pa ndryshim renditjeje.', 'Wenn {name} zustimmt, endet die Partie für euch beide: kein Sieger, keine Minuspunkte, keine Wertungsänderung.', 'Ako {name} pristane, partija se završava za oboje: bez pobjednika, bez izgubljenih bodova, bez promjene rejtinga.'],
    'agree.leave': ['Leave anyway – counts as lost', 'Largohu gjithsesi – llogaritet si humbje', 'Trotzdem gehen – zählt als verloren', 'Ipak izađi – računa se kao poraz'],
    'agree.stay': ['Keep playing', 'Vazhdo lojën', 'Weiterspielen', 'Nastavi igru'],
    'agree.sent': ['Asked. Waiting for {name} to answer…', 'U kërkua. Po presim përgjigjen e {name}…', 'Gefragt. Warten auf die Antwort von {name}…', 'Zahtjev poslan. Čekamo odgovor: {name}…'],
    'agree.title': ['End the match by agreement?', 'Ta mbyllim ndeshjen me marrëveshje?', 'Die Partie einvernehmlich beenden?', 'Završiti partiju dogovorom?'],
    'agree.text': ['{name} asks to end this match. If you agree, it ends for both of you and nothing counts: no winner, no points lost, no rating change.', '{name} kërkon ta mbyllni këtë ndeshje. Nëse pranon, ajo mbyllet për të dy dhe asgjë nuk llogaritet: pa fitues, pa pikë të humbura, pa ndryshim renditjeje.', '{name} möchte diese Partie beenden. Wenn du zustimmst, endet sie für euch beide und nichts zählt: kein Sieger, keine Minuspunkte, keine Wertungsänderung.', '{name} traži da završite ovu partiju. Ako pristaneš, završava se za oboje i ništa se ne računa: bez pobjednika, bez izgubljenih bodova, bez promjene rejtinga.'],
    'agree.yes': ['Agree – end it', 'Pranoj – mbylle', 'Einverstanden – beenden', 'Pristajem – završi'],
    'agree.declined': ['{name} wants to keep playing.', '{name} dëshiron të vazhdojë lojën.', '{name} möchte weiterspielen.', '{name} želi nastaviti igru.'],
    'agree.none': ['No answer from {name}. The match goes on.', 'Asnjë përgjigje nga {name}. Ndeshja vazhdon.', 'Keine Antwort von {name}. Die Partie geht weiter.', 'Nema odgovora: {name}. Partija se nastavlja.'],
    'agree.limit': ['You have already asked three times in this match.', 'Ke kërkuar tashmë tri herë në këtë ndeshje.', 'Du hast in dieser Partie schon dreimal gefragt.', 'Već si pitao/la tri puta u ovoj partiji.'],
    'void.agreed': ['You both agreed to end the match.', 'Të dy ratë dakord ta mbyllni ndeshjen.', 'Ihr habt euch geeinigt, die Partie zu beenden.', 'Oboje ste se dogovorili da završite partiju.'],
    // 1.1.6 - a match that is not the player's fault does not count; the connection looks after itself
    'quit.textEarly': ['No question has been asked yet. If you leave now, the match is cancelled for both of you and nothing counts.', 'Ende nuk është bërë asnjë pyetje. Nëse largohesh tani, ndeshja anulohet për të dy dhe asgjë nuk llogaritet.', 'Es wurde noch keine Frage gestellt. Wenn du jetzt gehst, wird die Partie für euch beide abgebrochen und nichts zählt.', 'Još nije postavljeno nijedno pitanje. Ako sada izađeš, partija se poništava za oboje i ništa se ne računa.'],
    'quit.textAway': ['Your opponent cannot be reached. If you leave, the match is cancelled and nothing counts.', 'Kundërshtari nuk po arrihet. Nëse largohesh, ndeshja anulohet dhe asgjë nuk llogaritet.', 'Dein Gegner ist nicht erreichbar. Wenn du gehst, wird die Partie abgebrochen und nichts zählt.', 'Protivnik nije dostupan. Ako izađeš, partija se poništava i ništa se ne računa.'],
    'quit.textDown': ['There is no connection to the match right now. If you leave, nothing counts against you.', 'Tani nuk ka lidhje me ndeshjen. Nëse largohesh, asgjë nuk llogaritet kundër teje.', 'Gerade besteht keine Verbindung zur Partie. Wenn du gehst, zählt nichts gegen dich.', 'Trenutno nema veze s partijom. Ako izađeš, ništa se ne računa protiv tebe.'],
    'quit.textRanked': ['The match has started: leaving now counts as a lost match, with red points and a lower rating.', 'Ndeshja ka filluar: largimi tani llogaritet si ndeshje e humbur, me pikë të kuqe dhe renditje më të ulët.', 'Die Partie läuft: Wer jetzt geht, verliert sie – mit roten Punkten und einer niedrigeren Wertung.', 'Partija je počela: izlazak sada se računa kao izgubljena partija, s crvenim bodovima i nižim rejtingom.'],
    'quit.textCounts': ['The match has started: leaving now counts as a lost match, with red points for an unfinished round.', 'Ndeshja ka filluar: largimi tani llogaritet si ndeshje e humbur, me pikë të kuqe për raundin e papërfunduar.', 'Die Partie läuft: Wer jetzt geht, verliert sie – mit roten Punkten für eine offene Runde.', 'Partija je počela: izlazak sada se računa kao izgubljena partija, s crvenim bodovima za nezavršenu rundu.'],
    'link.down': ['Connection lost – reconnecting… ({s})', 'Lidhja u ndërpre – po rilidhemi… ({s})', 'Verbindung unterbrochen – wird wiederhergestellt… ({s})', 'Veza prekinuta – ponovo se povezujemo… ({s})'],
    'link.back': ['Connected again.', 'U lidhëm përsëri.', 'Wieder verbunden.', 'Ponovo povezano.'],
    'link.longTitle': ['Still no connection', 'Ende pa lidhje', 'Immer noch keine Verbindung', 'Još uvijek nema veze'],
    'link.longText': ['The game keeps trying to get back into your match. You can also leave now: that is not your fault, so nothing counts against you.', 'Loja vazhdon të përpiqet të kthehet në ndeshjen tënde. Mund edhe të largohesh tani: nuk është faji yt, prandaj asgjë nuk llogaritet kundër teje.', 'Das Spiel versucht weiter, in deine Partie zurückzukommen. Du kannst jetzt auch gehen: Das ist nicht deine Schuld, also zählt nichts gegen dich.', 'Igra i dalje pokušava da se vrati u tvoju partiju. Možeš i sada izaći: nije tvoja krivica, pa se ništa ne računa protiv tebe.'],
    'link.leave': ['Leave – nothing counts', 'Largohu – asgjë nuk llogaritet', 'Verlassen – nichts zählt', 'Izađi – ništa se ne računa'],
