    'away.screen': ['{name} left the match screen – if {name} is not back in {s} s, the match is over.', '{name} e mbylli ekranin e ndeshjes – nëse nuk kthehet për {s} s, ndeshja mbaron.', '{name} hat den Spielbildschirm verlassen – ist {name} nicht in {s} s zurück, ist die Partie vorbei.', '{name} je napustio/la ekran partije – ako se ne vrati za {s} s, partija je gotova.'],
